def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or grid[r][c] == 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] not in (0, 5) and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append(comp)

    runs = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == 5:
                start = c
                while c < w and grid[r][c] == 5:
                    c += 1
                if c - start >= 2:
                    runs.append(("H", r, start, c - 1))
            else:
                c += 1

    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == 5:
                start = r
                while r < h and grid[r][c] == 5:
                    r += 1
                if r - start >= 2:
                    runs.append(("V", c, start, r - 1))
            else:
                r += 1

    for orient, fixed, lo, hi in runs:
        adjacent = []
        for comp in components:
            if orient == "H":
                touches = any(y in (fixed - 1, fixed + 1) and lo <= x <= hi for y, x in comp)
            else:
                touches = any(x in (fixed - 1, fixed + 1) and lo <= y <= hi for y, x in comp)
            if touches:
                adjacent.append(comp)
        if not adjacent:
            continue

        comp = max(adjacent, key=len)
        r0 = min(y for y, x in comp)
        r1 = max(y for y, x in comp)
        c0 = min(x for y, x in comp)
        c1 = max(x for y, x in comp)
        ph, pw = r1 - r0 + 1, c1 - c0 + 1
        pattern = [[grid[r0 + y][c0 + x] for x in range(pw)] for y in range(ph)]

        if orient == "H":
            for x in range(lo, hi + 1):
                for y in range(r0, r1 + 1):
                    out[y][x] = pattern[(y - r0) % ph][(x - c0) % pw]
        else:
            for y in range(lo, hi + 1):
                for x in range(c0, c1 + 1):
                    out[y][x] = pattern[(y - r0) % ph][(x - c0) % pw]

    return out
